    {
      "name": "cycle_time_budget",
      "value": "23.0",
      "units": "s",
      "narrative_section": "4.8"
    }
  ],
  "steps": [
    {
      "name": "IDLE",
      "entry": "Initial state or pallet cleared after DONE",
      "exit": "Pallet arrives in test position (ZS-2008 rising edge) with cell in auto mode, no ST20 fault active, and station idle"
    },
    {
      "name": "CLAMP",
      "entry": "Start conditions met; clamp solenoid XY-2002 energised",
      "exit": "Clamp confirmed closed (ZS-2002A made and ZS-2002B clear)"
    },
    {
      "name": "FILL",
      "entry": "Clamp confirmed closed; fill valve XV-2003 opened",
      "exit": "Pressure reaches fill complete threshold (14.50 kPa) or 8.0 s timeout occurs"
    },
    {
      "name": "STABILISE",
      "entry": "Fill complete reached; fill valve XV-2003 closed",
      "exit": "Stabilisation timer expires; baseline pressure recorded"
    },
    {
      "name": "TEST",
      "entry": "Stabilisation complete; pack remains isolated",
      "exit": "10.0 s test window timer expires; final pressure recorded and decay evaluated"
    },
    {
      "name": "VENT",
      "entry": "Test window complete (or fault/abort triggered); vent valve XV-2004 opened",
      "exit": "Vent timer expires, pack pressure is below 1.00 kPa, and PT-2001 signal is healthy"
    },
    {
      "name": "UNCLAMP",
      "entry": "Vent conditions satisfied; clamp solenoid XY-2002 de-energised",
      "exit": "Clamp confirmed open (ZS-2002B made and ZS-2002A clear)"
    },
    {
      "name": "DONE",
      "entry": "Clamp confirmed open; PASS or FAIL signal output to line controller",
      "exit": "Pallet departs from test position (ZS-2008 clear)"
    }
  ],
  "interlocks": [
    {
      "cause": "Clamp not confirmed closed (ZS-2002A lost or ZS-2002B made)",
      "effect": "Fill valve XV-2003 closed immediately / fill inhibited"
    },
    {
      "cause": "Pack pressure not below 1.00 kPa or PT-2001 signal fault active",
      "effect": "Clamp release inhibited; station holds in VENT with vent valve open"
    },
    {
      "cause": "ST20 fault active, auto mode not selected, or station not idle",
      "effect": "Cycle start inhibited"
    },
    {
      "cause": "Pallet sensor drops and returns while test is running",
      "effect": "Sequence restart inhibited"
    },
    {
      "cause": "Manual vent pushbutton PB-2010 pressed in manual mode",
      "effect": "Vent valve XV-2004 opened"
    },
    {
      "cause": "E-stop chain lost during active cycle",
      "effect": "Cycle aborts immediately to VENT with FAIL result"
    }
  ],
  "alarms": [
    {
      "name": "Fill timeout",
      "condition": "PT-2001 does not reach 14.50 kPa within 8.0 s of fill start",
      "action": "Abort to VENT, assign FAIL result, energise fault beacon HL-2011"
    },
    {
      "name": "Over-pressure",
      "condition": "PT-2001 pressure reading exceeds 20.00 kPa (latched)",
      "action": "Close fill valve, hold vent valve open, assign FAIL result, energise fault beacon HL-2011"
    },
    {
      "name": "PT-2001 signal fault",
      "condition": "PT-2001 pressure reading drops below -5.00 kPa (wire break)",
      "action": "Inhibit cycle start, inhibit unclamp, energise fault beacon HL-2011"
    },
    {
      "name": "Supply air low",
      "condition": "Supply air pressure switch PS-2009 lost while station is busy (latched)",
      "action": "Abort to VENT, assign FAIL result, energise fault beacon HL-2011"
    }
  ],
  "conflicts": [
    {
      "item": "stabilise_time",
      "narrative_says": "3 s",
      "parameter_sheet_says": "5.0 s",
      "program_says": "5.0 s (R13 OUT T22 K50)",
      "authoritative": "parameter sheet"
    },
    {
      "item": "vent_time",
      "narrative_says": "0.5 s",
      "parameter_sheet_says": "0.5 s",
      "program_says": "5.0 s (R21 OUT T200 K50; on FX5, OUT has a 100 ms base making K50 equal to 5.0 s)",
      "authoritative": "parameter sheet"
    },
    {
      "item": "test_pressure",
      "narrative_says": "15.2 kPa",
      "parameter_sheet_says": "15.00 kPa(g) (note notes regulator PR-2012 set to 15.2 kPa)",
      "program_says": "Not programmed in PLC (mechanical regulator)",
      "authoritative": "parameter sheet"
    }
  ]
}
